CREATE TABLE IF NOT EXISTS peppol_submission_events (
  id INTEGER PRIMARY KEY,
  submission_id INTEGER NOT NULL REFERENCES peppol_submissions(id),
  event_type TEXT NOT NULL CHECK(event_type IN ('delivery_reserved','delivery_failed','queued','status_observed','delivered')),
  document_id TEXT,
  status TEXT,
  observed_at TEXT NOT NULL,
  message TEXT NOT NULL DEFAULT '',
  public_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_peppol_submission_events_submission
  ON peppol_submission_events(submission_id, id DESC);
CREATE TRIGGER IF NOT EXISTS peppol_submission_events_no_update
BEFORE UPDATE ON peppol_submission_events
BEGIN
  SELECT RAISE(ABORT, 'peppol submission events are append-only');
END;
CREATE TRIGGER IF NOT EXISTS peppol_submission_events_no_delete
BEFORE DELETE ON peppol_submission_events
BEGIN
  SELECT RAISE(ABORT, 'peppol submission events are append-only');
END;

DROP TRIGGER IF EXISTS recurring_invoice_templates_guard_update;
DROP TRIGGER IF EXISTS recurring_invoice_generations_no_update;
DROP TRIGGER IF EXISTS recurring_invoice_generations_no_delete;
DROP TABLE IF EXISTS recurring_invoice_templates_v3;
DROP TABLE IF EXISTS recurring_invoice_generations_v3_backup;
CREATE TABLE recurring_invoice_templates_v3 (id INTEGER PRIMARY KEY, name TEXT NOT NULL, interval TEXT NOT NULL CHECK(interval IN ('weekly','monthly','quarterly','yearly')), interval_count INTEGER NOT NULL DEFAULT 1 CHECK(interval_count BETWEEN 1 AND 120), delivery_channel TEXT NOT NULL DEFAULT 'manual' CHECK(delivery_channel IN ('manual','email','digisense')), first_issue_date TEXT NOT NULL, next_issue_date TEXT NOT NULL, payment_terms_days INTEGER NOT NULL DEFAULT 30 CHECK(payment_terms_days BETWEEN 0 AND 365), delivery_period_mode TEXT NOT NULL DEFAULT 'issue_month' CHECK(delivery_period_mode IN ('issue_month','interval_window','none')), payload_json TEXT NOT NULL, notes TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO recurring_invoice_templates_v3 (id,name,interval,interval_count,delivery_channel,first_issue_date,next_issue_date,payment_terms_days,delivery_period_mode,payload_json,notes,active,created_at) SELECT id,name,interval,1,'manual',first_issue_date,next_issue_date,payment_terms_days,delivery_period_mode,payload_json,notes,active,created_at FROM recurring_invoice_templates;
CREATE TABLE recurring_invoice_generations_v3_backup AS SELECT id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at FROM recurring_invoice_generations;
DROP TABLE recurring_invoice_generations;
DROP TABLE recurring_invoice_templates;
ALTER TABLE recurring_invoice_templates_v3 RENAME TO recurring_invoice_templates;
CREATE TABLE recurring_invoice_generations (id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES recurring_invoice_templates(id), period_index INTEGER NOT NULL CHECK(period_index >= 0), document_id INTEGER NOT NULL REFERENCES documents(id), invoice_number TEXT NOT NULL, issue_date TEXT NOT NULL, delivery_period_start TEXT, delivery_period_end TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(template_id,period_index));
INSERT INTO recurring_invoice_generations (id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at) SELECT id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at FROM recurring_invoice_generations_v3_backup;
DROP TABLE recurring_invoice_generations_v3_backup;
CREATE INDEX idx_recurring_invoice_generations_template ON recurring_invoice_generations(template_id,period_index);
CREATE TABLE IF NOT EXISTS recurring_invoice_generation_claims (id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES recurring_invoice_templates(id), period_index INTEGER NOT NULL CHECK(period_index >= 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(template_id,period_index));
INSERT OR IGNORE INTO recurring_invoice_generation_claims(template_id,period_index) SELECT template_id,period_index FROM recurring_invoice_generations;
CREATE TABLE IF NOT EXISTS recurring_invoice_delivery_events (id INTEGER PRIMARY KEY, generation_id INTEGER NOT NULL REFERENCES recurring_invoice_generations(id), channel TEXT NOT NULL CHECK(channel IN ('email','digisense')), event_type TEXT NOT NULL CHECK(event_type IN ('attempted','acknowledged','accepted_pending','terminal_failed','uncertain','preflight_failed')), provider_id TEXT, message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_recurring_invoice_delivery_events_generation ON recurring_invoice_delivery_events(generation_id,id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_recurring_invoice_delivery_single_attempt ON recurring_invoice_delivery_events(generation_id) WHERE event_type = 'attempted';
CREATE TRIGGER recurring_invoice_templates_guard_update BEFORE UPDATE ON recurring_invoice_templates WHEN OLD.name != NEW.name OR OLD.interval != NEW.interval OR OLD.interval_count != NEW.interval_count OR OLD.delivery_channel != NEW.delivery_channel OR OLD.first_issue_date != NEW.first_issue_date OR OLD.payment_terms_days != NEW.payment_terms_days OR OLD.delivery_period_mode != NEW.delivery_period_mode OR OLD.payload_json != NEW.payload_json OR OLD.created_at != NEW.created_at OR NEW.next_issue_date < OLD.next_issue_date OR (OLD.active = 0 AND NEW.active = 1) BEGIN SELECT RAISE(ABORT, 'recurring invoice templates are append-only; only next_issue_date may advance and active may be retired'); END;
CREATE TRIGGER recurring_invoice_templates_no_delete BEFORE DELETE ON recurring_invoice_templates BEGIN SELECT RAISE(ABORT, 'recurring invoice templates are append-only; retire them with active = 0 instead'); END;
CREATE TRIGGER recurring_invoice_generations_no_update BEFORE UPDATE ON recurring_invoice_generations BEGIN SELECT RAISE(ABORT, 'recurring invoice generations are append-only audit links; issue a credit note on the generated invoice instead'); END;
CREATE TRIGGER recurring_invoice_generations_no_delete BEFORE DELETE ON recurring_invoice_generations BEGIN SELECT RAISE(ABORT, 'recurring invoice generations are append-only audit links; issue a credit note on the generated invoice instead'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_generation_claims_no_update BEFORE UPDATE ON recurring_invoice_generation_claims BEGIN SELECT RAISE(ABORT, 'recurring invoice generation claims are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_generation_claims_no_delete BEFORE DELETE ON recurring_invoice_generation_claims BEGIN SELECT RAISE(ABORT, 'recurring invoice generation claims are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_delivery_events_no_update BEFORE UPDATE ON recurring_invoice_delivery_events BEGIN SELECT RAISE(ABORT, 'recurring invoice delivery events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_delivery_events_no_delete BEFORE DELETE ON recurring_invoice_delivery_events BEGIN SELECT RAISE(ABORT, 'recurring invoice delivery events are append-only'); END;

CREATE TABLE IF NOT EXISTS dinero_import_sources (
  id INTEGER PRIMARY KEY,
  raw_sha256 TEXT NOT NULL UNIQUE CHECK(length(raw_sha256) = 64 AND raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  raw_size_bytes INTEGER NOT NULL CHECK(raw_size_bytes >= 0),
  canonical_listing_sha256 TEXT NOT NULL CHECK(length(canonical_listing_sha256) = 64 AND canonical_listing_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_count INTEGER NOT NULL CHECK(canonical_listing_count >= 0),
  received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, raw_sha256),
  UNIQUE(id, raw_sha256, canonical_listing_sha256, canonical_listing_count)
);
CREATE TABLE IF NOT EXISTS dinero_import_inventories (
  id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_sha256 TEXT NOT NULL CHECK(length(canonical_listing_sha256) = 64 AND canonical_listing_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_count INTEGER NOT NULL CHECK(canonical_listing_count >= 0),
  entry_count INTEGER NOT NULL CHECK(entry_count >= 0), total_size_bytes INTEGER NOT NULL CHECK(total_size_bytes >= 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, source_id, source_raw_sha256),
  FOREIGN KEY(source_id, source_raw_sha256, canonical_listing_sha256, canonical_listing_count) REFERENCES dinero_import_sources(id, raw_sha256, canonical_listing_sha256, canonical_listing_count)
);
CREATE TABLE IF NOT EXISTS dinero_import_inventory_entries (
  id INTEGER PRIMARY KEY, inventory_id INTEGER NOT NULL REFERENCES dinero_import_inventories(id),
  entry_path TEXT NOT NULL CHECK(length(entry_path) > 0 AND substr(entry_path, 1, 1) != '/' AND instr(entry_path, '..') = 0),
  entry_size_bytes INTEGER NOT NULL CHECK(entry_size_bytes >= 0),
  entry_sha256 TEXT NOT NULL CHECK(length(entry_sha256) = 64 AND entry_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  UNIQUE(inventory_id, entry_path), UNIQUE(inventory_id, entry_path, entry_sha256)
);
CREATE TABLE IF NOT EXISTS dinero_import_attempts (
  id INTEGER PRIMARY KEY, inventory_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  parser_contract TEXT NOT NULL CHECK(length(parser_contract) > 0), actor TEXT NOT NULL CHECK(length(actor) > 0),
  cutover_date TEXT NOT NULL CHECK(length(cutover_date) = 10),
  outcome TEXT NOT NULL CHECK(outcome IN ('accepted','rejected')),
  result_sha256 TEXT NOT NULL CHECK(length(result_sha256) = 64 AND result_sha256 NOT GLOB '*[^0-9a-fA-F]*'), recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, inventory_id), UNIQUE(id, inventory_id, source_id, source_raw_sha256),
  FOREIGN KEY(inventory_id, source_id, source_raw_sha256) REFERENCES dinero_import_inventories(id, source_id, source_raw_sha256)
);
CREATE TABLE IF NOT EXISTS dinero_import_archive_evidence (
  id INTEGER PRIMARY KEY, attempt_id INTEGER NOT NULL, inventory_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  fiscal_year INTEGER NOT NULL CHECK(fiscal_year BETWEEN 1 AND 9999), archive_sha256 TEXT NOT NULL CHECK(length(archive_sha256) = 64 AND archive_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  archive_size_bytes INTEGER NOT NULL CHECK(archive_size_bytes >= 0), UNIQUE(attempt_id, fiscal_year),
  FOREIGN KEY(attempt_id, inventory_id, source_id, source_raw_sha256) REFERENCES dinero_import_attempts(id, inventory_id, source_id, source_raw_sha256)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_documents_id_sha256_hash ON documents(id, sha256_hash);
CREATE TABLE IF NOT EXISTS dinero_import_document_links (
  id INTEGER PRIMARY KEY, attempt_id INTEGER NOT NULL, inventory_id INTEGER NOT NULL, entry_path TEXT NOT NULL, entry_sha256 TEXT NOT NULL CHECK(length(entry_sha256) = 64 AND entry_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  document_id INTEGER NOT NULL REFERENCES documents(id), journal_entry_id INTEGER REFERENCES journal_entries(id), voucher_reference TEXT,
  disposition TEXT NOT NULL CHECK(disposition IN ('linked','unmatched','excluded')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(attempt_id, entry_path, entry_sha256),
  FOREIGN KEY(attempt_id, inventory_id) REFERENCES dinero_import_attempts(id, inventory_id),
  FOREIGN KEY(inventory_id, entry_path, entry_sha256) REFERENCES dinero_import_inventory_entries(inventory_id, entry_path, entry_sha256),
  FOREIGN KEY(document_id, entry_sha256) REFERENCES documents(id, sha256_hash)
);
CREATE INDEX IF NOT EXISTS idx_dinero_import_inventory_entries_inventory ON dinero_import_inventory_entries(inventory_id, entry_path);
CREATE INDEX IF NOT EXISTS idx_dinero_import_archive_evidence_attempt ON dinero_import_archive_evidence(attempt_id, fiscal_year);
CREATE INDEX IF NOT EXISTS idx_dinero_import_document_links_document ON dinero_import_document_links(document_id);
CREATE TRIGGER dinero_import_sources_no_update BEFORE UPDATE ON dinero_import_sources BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_sources_no_delete BEFORE DELETE ON dinero_import_sources BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_inventories_no_update BEFORE UPDATE ON dinero_import_inventories BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_inventories_no_delete BEFORE DELETE ON dinero_import_inventories BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_inventory_entries_no_update BEFORE UPDATE ON dinero_import_inventory_entries BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_inventory_entries_no_delete BEFORE DELETE ON dinero_import_inventory_entries BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_attempts_no_update BEFORE UPDATE ON dinero_import_attempts BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_attempts_no_delete BEFORE DELETE ON dinero_import_attempts BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_archive_evidence_no_update BEFORE UPDATE ON dinero_import_archive_evidence BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_archive_evidence_no_delete BEFORE DELETE ON dinero_import_archive_evidence BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_document_links_no_update BEFORE UPDATE ON dinero_import_document_links BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;
CREATE TRIGGER dinero_import_document_links_no_delete BEFORE DELETE ON dinero_import_document_links BEGIN SELECT RAISE(ABORT, 'dinero import provenance is append-only'); END;

CREATE TABLE IF NOT EXISTS migration_open_item_batches (
  id INTEGER PRIMARY KEY,
  dinero_import_attempt_id INTEGER NOT NULL REFERENCES dinero_import_attempts(id),
  control_account_no TEXT NOT NULL REFERENCES accounts(account_no),
  kind TEXT NOT NULL CHECK(kind IN ('receivable','payable')),
  source_control_amount NUMERIC NOT NULL CHECK(source_control_amount >= 0),
  opening_journal_entry_id INTEGER REFERENCES journal_entries(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(dinero_import_attempt_id, control_account_no)
);
CREATE TABLE IF NOT EXISTS migration_open_items (
  id INTEGER PRIMARY KEY,
  batch_id INTEGER NOT NULL REFERENCES migration_open_item_batches(id),
  external_ref TEXT NOT NULL CHECK(length(trim(external_ref)) > 0),
  counterparty_name TEXT,
  issue_date TEXT CHECK(issue_date IS NULL OR length(issue_date) = 10),
  due_date TEXT CHECK(due_date IS NULL OR length(due_date) = 10),
  original_amount NUMERIC NOT NULL CHECK(original_amount > 0),
  open_amount_at_import NUMERIC NOT NULL CHECK(open_amount_at_import > 0 AND open_amount_at_import <= original_amount),
  document_id INTEGER REFERENCES documents(id),
  source_recognition_journal_entry_id INTEGER REFERENCES journal_entries(id),
  source_kind TEXT NOT NULL CHECK(source_kind IN ('opening','journal','control_balance')),
  resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','unallocated')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(batch_id, external_ref),
  UNIQUE(source_recognition_journal_entry_id),
  CHECK((source_kind IN ('opening','control_balance') AND source_recognition_journal_entry_id IS NULL) OR (source_kind = 'journal' AND source_recognition_journal_entry_id IS NOT NULL)),
  CHECK((resolution_status = 'resolved' AND counterparty_name IS NOT NULL AND length(trim(counterparty_name)) > 0 AND issue_date IS NOT NULL) OR (resolution_status = 'unallocated' AND counterparty_name IS NULL AND issue_date IS NULL AND due_date IS NULL AND document_id IS NULL AND source_kind IN ('opening','control_balance')))
);
CREATE TABLE IF NOT EXISTS migration_open_item_applications (
  id INTEGER PRIMARY KEY,
  item_id INTEGER NOT NULL REFERENCES migration_open_items(id),
  amount NUMERIC NOT NULL CHECK(amount > 0),
  application_date TEXT NOT NULL CHECK(length(application_date) = 10),
  source_journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),
  bank_transaction_id INTEGER REFERENCES bank_transactions(id),
  note TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_migration_open_item_application_journal ON migration_open_item_applications(source_journal_entry_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_migration_open_item_application_bank ON migration_open_item_applications(bank_transaction_id) WHERE bank_transaction_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_migration_open_items_batch ON migration_open_items(batch_id, external_ref);
CREATE INDEX IF NOT EXISTS idx_migration_open_item_applications_item ON migration_open_item_applications(item_id, id);
CREATE TRIGGER migration_open_item_application_balance_guard BEFORE INSERT ON migration_open_item_applications WHEN CAST(ROUND(100 * (NEW.amount + COALESCE((SELECT SUM(amount) FROM migration_open_item_applications WHERE item_id = NEW.item_id), 0))) AS INTEGER) > CAST(ROUND(100 * (SELECT open_amount_at_import FROM migration_open_items WHERE id = NEW.item_id)) AS INTEGER) BEGIN SELECT RAISE(ABORT, 'migration open-item application would over-apply the open balance'); END;
CREATE TRIGGER migration_open_item_batches_no_update BEFORE UPDATE ON migration_open_item_batches BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_batches_no_delete BEFORE DELETE ON migration_open_item_batches BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_items_no_update BEFORE UPDATE ON migration_open_items BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_items_no_delete BEFORE DELETE ON migration_open_items BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_applications_no_update BEFORE UPDATE ON migration_open_item_applications BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_applications_no_delete BEFORE DELETE ON migration_open_item_applications BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;

CREATE TABLE IF NOT EXISTS bank_journal_reconciliation_links (
  id INTEGER PRIMARY KEY,
  bank_transaction_id INTEGER NOT NULL REFERENCES bank_transactions(id),
  journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),
  match_method TEXT NOT NULL CHECK(match_method IN ('exact-date-amount','settlement-lag-amount','source-reference','manual-review')),
  source_reference TEXT,
  note TEXT,
  created_by TEXT NOT NULL,
  created_by_program TEXT NOT NULL DEFAULT 'rentemester',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(bank_transaction_id),
  UNIQUE(bank_transaction_id, journal_entry_id),
  CHECK(source_reference IS NULL OR length(trim(source_reference)) > 0),
  CHECK(note IS NULL OR length(trim(note)) > 0)
);
CREATE TRIGGER bank_journal_reconciliation_links_guard_insert BEFORE INSERT ON bank_journal_reconciliation_links WHEN NOT EXISTS (SELECT 1 FROM bank_transactions bt JOIN bank_accounts ba ON ba.id = bt.bank_account_id WHERE bt.id = NEW.bank_transaction_id AND ba.ledger_account_no IS NOT NULL) OR NOT EXISTS (SELECT 1 FROM journal_entries je WHERE je.id = NEW.journal_entry_id AND je.status = 'posted' AND je.reversal_of_entry_id IS NULL) OR EXISTS (SELECT 1 FROM journal_entries je WHERE je.source_bank_transaction_id = NEW.bank_transaction_id) OR EXISTS (SELECT 1 FROM journal_entries je WHERE je.id = NEW.journal_entry_id AND je.source_bank_transaction_id IS NOT NULL) OR EXISTS (SELECT 1 FROM journal_entries reversal WHERE reversal.reversal_of_entry_id = NEW.journal_entry_id) OR NOT EXISTS (SELECT 1 FROM bank_transactions bt JOIN bank_accounts ba ON ba.id = bt.bank_account_id JOIN accounts a ON a.account_no = ba.ledger_account_no JOIN journal_lines jl ON jl.account_id = a.id AND jl.journal_entry_id = NEW.journal_entry_id WHERE bt.id = NEW.bank_transaction_id GROUP BY bt.id HAVING CAST(ROUND(100 * SUM(jl.debit_amount - jl.credit_amount)) AS INTEGER) = CAST(ROUND(100 * CASE WHEN UPPER(bt.currency) = 'DKK' THEN bt.amount ELSE bt.amount_dkk END) AS INTEGER)) BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation link requires an active unlinked journal whose mapped-bank movement equals the bank transaction in DKK'); END;
CREATE TRIGGER bank_journal_reconciliation_links_no_update BEFORE UPDATE ON bank_journal_reconciliation_links BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation links are append-only'); END;
CREATE TRIGGER bank_journal_reconciliation_links_no_delete BEFORE DELETE ON bank_journal_reconciliation_links BEGIN SELECT RAISE(ABORT, 'bank-journal reconciliation links are append-only'); END;
CREATE TRIGGER journal_entries_bank_reconciliation_link_conflict BEFORE INSERT ON journal_entries WHEN NEW.source_bank_transaction_id IS NOT NULL AND EXISTS (SELECT 1 FROM bank_journal_reconciliation_links link WHERE link.bank_transaction_id = NEW.source_bank_transaction_id) BEGIN SELECT RAISE(ABORT, 'bank transaction already has an append-only reconciliation link'); END;
DROP TRIGGER IF EXISTS bank_transactions_no_update_when_referenced;
CREATE TRIGGER bank_transactions_no_update_when_referenced BEFORE UPDATE ON bank_transactions WHEN EXISTS(SELECT 1 FROM journal_entries WHERE source_bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM bank_journal_reconciliation_links WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_payments WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_refunds WHERE bank_transaction_id = OLD.id) OR EXISTS(SELECT 1 FROM invoice_claim_payments WHERE bank_transaction_id = OLD.id) BEGIN SELECT RAISE(ABORT, 'bank transaction is referenced by ledger, reconciliation, or payment records and cannot be modified'); END;
CREATE VIEW IF NOT EXISTS bank_journal_reconciliations AS SELECT je.source_bank_transaction_id AS bank_transaction_id, je.id AS journal_entry_id, je.entry_no AS journal_entry_no, 'direct' AS link_kind FROM journal_entries je WHERE je.source_bank_transaction_id IS NOT NULL AND je.status = 'posted' UNION ALL SELECT link.bank_transaction_id, je.id, je.entry_no, 'append-only' FROM bank_journal_reconciliation_links link JOIN journal_entries je ON je.id = link.journal_entry_id WHERE je.status = 'posted';

